import os
import tokenize

root = os.getcwd()
hits = set()

for dirpath, dirnames, filenames in os.walk(root):
    dirnames[:] = [d for d in dirnames if d != '.git']
    for name in filenames:
        if not name.endswith('.py'):
            continue
        full = os.path.join(dirpath, name)
        rel = os.path.relpath(full, root).replace(os.sep, '/')
        try:
            with tokenize.open(full) as f:
                src = f.read()
            for tok in tokenize.generate_tokens(io.StringIO(src).readline):
                if tok.type == tokenize.COMMENT and 'TODO' in tok.string:
                    hits.add((rel, tok.start[0]))
        except (SyntaxError, tokenize.TokenError, UnicodeDecodeError, OSError):
            print('skipped: ' + rel)

lines = [f'{p}:{n}' for p, n in sorted(hits)]
with open(os.path.join(root, 'todos.txt'), 'w') as out:
    out.write('\n'.join(lines) + ('\n' if lines else ''))
print('\n'.join(lines))
